<?php
function eHist(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function moneyHist(float $v): string { return 'R$ '.number_format($v,2,',','.'); }
$tipo = (string)($usuario['tipo']??'');
$voltar = $tipo==='cliente' ? '/cliente/dashboard.php' : '/desenvolvedor/dashboard.php';
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Histórico - SiteMatch</title><link rel="stylesheet" href="/css/global.css"><link rel="stylesheet" href="/css/dashboard.css"><link rel="stylesheet" href="/css/functional.css"></head><body><main class="dashboard-main" style="max-width:1050px;margin:0 auto;"><p style="margin-bottom:20px;"><a href="<?= eHist($voltar) ?>">← Voltar ao painel</a></p><header class="dashboard-header"><div class="dashboard-header-text"><h1>Histórico</h1><p>Consulte projetos, propostas e contratações encerradas.</p></div></header>
<?php if(empty($registros)): ?><div class="projetos-vazio">Ainda não há registros finalizados no seu histórico.</div><?php else: ?><div class="lista-simples"><?php foreach($registros as $r): ?><article class="projeto-card"><div class="projeto-card-topo"><div><h3><?= eHist((string)$r['projeto_titulo']) ?></h3><p style="margin-top:5px;"><?= $tipo==='cliente' ? 'Desenvolvedor: '.eHist((string)($r['desenvolvedor_nome']??'—')) : 'Cliente: '.eHist((string)($r['cliente_nome']??'—')) ?></p></div><span class="projeto-status"><?= eHist((string)($r['contratacao_status']??$r['proposta_status']??$r['projeto_status']??'')) ?></span></div><div class="projeto-meta" style="margin-top:16px;"><?php if(isset($r['valor_final']) && $r['valor_final']!==null): ?><span>Valor final: <strong><?= moneyHist((float)$r['valor_final']) ?></strong></span><?php elseif(isset($r['valor'])): ?><span>Valor da proposta: <strong><?= moneyHist((float)$r['valor']) ?></strong></span><?php endif; ?><?php if(!empty($r['nota'])): ?><span>Avaliação: <strong>★ <?= (int)$r['nota'] ?>/5</strong></span><?php endif; ?></div><?php if(!empty($r['comentario'])): ?><p style="margin-top:12px;"><?= eHist((string)$r['comentario']) ?></p><?php endif; ?><?php if(!empty($r['contratacao_id'])): ?><div class="acoes-inline"><a class="botao-secundario" href="/contratacao.php?id=<?= (int)$r['contratacao_id'] ?>">Ver contratação</a></div><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
</main></body></html>
